use anyhow::Result;
use xline_client::{Client, ClientOptions};

#[tokio::main]
async fn main() -> Result<()> {
    // the name and address of all curp members
    let curp_members = ["10.0.0.1:2379", "10.0.0.2:2379", "10.0.0.3:2379"];

    let mut client = Client::connect(curp_members, ClientOptions::default())
        .await?
        .cluster_client();

    // send a linearizable member list request
    let resp = client.member_list(true).await?;
    println!("members: {:?}", resp.members);

    // whether the added member is a learner.
    // the learner does not participate in voting and will only catch up with the progress of the leader.
    let is_learner = true;

    // add a normal node into the cluster
    let resp = client.member_add(["127.0.0.1:2379"], is_learner).await?;
    let added_member = resp.member.unwrap();
    println!("members: {:?}, added: {}", resp.members, added_member.id);

    if is_learner {
        // promote the learner to a normal node
        let resp = client.member_promote(added_member.id).await?;
        println!("members: {:?}", resp.members);
    }

    // update the peer_ur_ls of the added member if the network topology has changed.
    let resp = client
        .member_update(added_member.id, ["127.0.0.2:2379"])
        .await?;
    println!("members: {:?}", resp.members);

    // remove the member from the cluster if it is no longer needed.
    let resp = client.member_remove(added_member.id).await?;
    println!("members: {:?}", resp.members);

    Ok(())
}

//! An example to show how the errors are organized in `xline-client`
use anyhow::Result;
use xline_client::{error::XlineClientError, types::kv::PutOptions, Client, ClientOptions};
use xlineapi::execute_error::ExecuteError;

#[tokio::main]
async fn main() -> Result<()> {
    // the name and address of all curp members
    let curp_members = ["10.0.0.1:2379", "10.0.0.2:2379", "10.0.0.3:2379"];

    let client = Client::connect(curp_members, ClientOptions::default())
        .await?
        .kv_client();

    // We try to update the key using its previous value.
    // It should return an error and it should be `key not found`
    // as we did not add it before.
    let resp = client
        .put(
            "key",
            "",
            Some(PutOptions::default().with_ignore_value(true)),
        )
        .await;
    let err = resp.unwrap_err();

    // We match the inner error returned by the Curp server.
    // The command should failed at execution stage.
    let XlineClientError::CommandError(ee) = err else {
        unreachable!("the propose error should be an Execute error, but it is {err:?}")
    };

    assert!(
        matches!(ee, ExecuteError::KeyNotFound),
        "the return result should be `KeyNotFound`"
    );
    println!("got error: {ee}");

    Ok(())
}

use anyhow::Result;
use xline_client::{
    types::kv::{Compare, CompareResult, DeleteRangeOptions, PutOptions, TxnOp, TxnRequest},
    Client, ClientOptions,
};

#[tokio::main]
async fn main() -> Result<()> {
    // the name and address of all curp members
    let curp_members = ["10.0.0.1:2379", "10.0.0.2:2379", "10.0.0.3:2379"];

    let client = Client::connect(curp_members, ClientOptions::default())
        .await?
        .kv_client();

    // put
    client.put("key1", "value1", None).await?;
    client.put("key2", "value2", None).await?;

    // range
    let resp = client.range("key1", None).await?;

    if let Some(kv) = resp.kvs.first() {
        println!(
            "got key: {}, value: {}",
            String::from_utf8_lossy(&kv.key),
            String::from_utf8_lossy(&kv.value)
        );
    }

    // delete
    let resp = client
        .delete(
            "key1",
            Some(DeleteRangeOptions::default().with_prev_kv(true)),
        )
        .await?;

    for kv in resp.prev_kvs {
        println!(
            "deleted key: {}, value: {}",
            String::from_utf8_lossy(&kv.key),
            String::from_utf8_lossy(&kv.value)
        );
    }

    // txn
    let txn_req = TxnRequest::new()
        .when(&[Compare::value("key2", CompareResult::Equal, "value2")][..])
        .and_then(
            &[TxnOp::put(
                "key2",
                "value3",
                Some(PutOptions::default().with_prev_kv(true)),
            )][..],
        )
        .or_else(&[TxnOp::range("key2", None)][..]);

    let _resp = client.txn(txn_req).await?;
    let resp = client.range("key2", None).await?;
    // should print "value3"
    if let Some(kv) = resp.kvs.first() {
        println!(
            "got key: {}, value: {}",
            String::from_utf8_lossy(&kv.key),
            String::from_utf8_lossy(&kv.value)
        );
    }

    // compact
    let rev = resp.header.unwrap().revision;
    let _resp = client.compact(rev, false).await?;

    Ok(())
}

use anyhow::Result;
use xline_client::{Client, ClientOptions};

#[tokio::main]
async fn main() -> Result<()> {
    // the name and address of all curp members
    let curp_members = ["10.0.0.1:2379", "10.0.0.2:2379", "10.0.0.3:2379"];

    let mut client = Client::connect(curp_members, ClientOptions::default())
        .await?
        .lease_client();

    // grant new lease
    let resp1 = client.grant(60, None).await?;
    let resp2 = client.grant(60, None).await?;
    let lease_id1 = resp1.id;
    let lease_id2 = resp2.id;
    println!("lease id 1: {}", lease_id1);
    println!("lease id 2: {}", lease_id2);

    // get the ttl of lease1
    let resp = client.time_to_live(lease_id1, false).await?;

    println!("remaining ttl: {}", resp.ttl);

    // keep alive lease2
    let (mut keeper, mut stream) = client.keep_alive(lease_id2).await?;

    if let Some(resp) = stream.message().await? {
        println!("new ttl: {}", resp.ttl);
    }

    // keep alive lease2 again using the keeper
    keeper.keep_alive()?;

    // list all leases
    for lease in client.leases().await?.leases {
        println!("lease: {}", lease.id);
    }

    // revoke the leases
    let _resp = client.revoke(lease_id1).await?;
    let _resp = client.revoke(lease_id2).await?;

    Ok(())
}

use anyhow::Result;
use xline_client::{
    clients::Xutex,
    types::kv::{Compare, CompareResult, PutOptions, TxnOp},
    Client, ClientOptions,
};

#[tokio::main]
async fn main() -> Result<()> {
    // the name and address of all curp members
    let curp_members = ["10.0.0.1:2379", "10.0.0.2:2379", "10.0.0.3:2379"];

    let client = Client::connect(curp_members, ClientOptions::default()).await?;

    let lock_client = client.lock_client();
    let kv_client = client.kv_client();

    let mut xutex = Xutex::new(lock_client, "lock-test", None, None).await?;
    // when the `xutex_guard` drop, the lock will be unlocked.
    let xutex_guard = xutex.lock_unsafe().await?;

    let txn_req = xutex_guard
        .txn_check_locked_key()
        .when([Compare::value("key2", CompareResult::Equal, "value2")])
        .and_then([TxnOp::put(
            "key2",
            "value3",
            Some(PutOptions::default().with_prev_kv(true)),
        )])
        .or_else(&[]);

    let _resp = kv_client.txn(txn_req).await?;

    Ok(())
}

use anyhow::Result;
use xline_client::{Client, ClientOptions};

#[tokio::main]
async fn main() -> Result<()> {
    // the name and address of all curp members
    let curp_members = ["10.0.0.1:2379", "10.0.0.2:2379", "10.0.0.3:2379"];

    let mut client = Client::connect(curp_members, ClientOptions::default())
        .await?
        .maintenance_client();

    // snapshot
    let mut msg = client.snapshot().await?;
    let mut snapshot = vec![];
    loop {
        if let Some(resp) = msg.message().await? {
            snapshot.extend_from_slice(&resp.blob);
            if resp.remaining_bytes == 0 {
                break;
            }
        }
    }
    println!("snapshot size: {}", snapshot.len());

    Ok(())
}

use anyhow::Result;
use xline_client::{Client, ClientOptions};

#[tokio::main]
async fn main() -> Result<()> {
    // the name and address of all curp members
    let curp_members = ["10.0.0.1:2379", "10.0.0.2:2379", "10.0.0.3:2379"];

    let client = Client::connect(curp_members, ClientOptions::default()).await?;
    let mut watch_client = client.watch_client();
    let kv_client = client.kv_client();

    // watch
    let (mut watcher, mut stream) = watch_client.watch("key1", None).await?;
    kv_client.put("key1", "value1", None).await?;

    let resp = stream.message().await?.unwrap();
    let kv = resp.events[0].kv.as_ref().unwrap();

    println!(
        "got key: {}, value: {}",
        String::from_utf8_lossy(&kv.key),
        String::from_utf8_lossy(&kv.value)
    );

    // cancel the watch
    watcher.cancel()?;

    Ok(())
}

use anyhow::Result;

#[cfg(feature = "cgroupsv2_devices")]
mod bpf {
    use std::os::unix::io::AsRawFd;
    use std::path::Path;

    use anyhow::{Result, bail};
    use clap::{Arg, Command};
    use libcgroups::v2::devices::{bpf, emulator, program};
    use nix::fcntl::OFlag;
    use nix::sys::stat::Mode;
    use oci_spec::runtime::LinuxDeviceCgroup;

    const LICENSE: &str = "Apache";
    fn cli() -> Command {
        clap::Command::new("bpf")
            .version("0.1")
            .about("tools to test BPF program for cgroups v2 devices")
            .arg(Arg::new("cgroup_dir").short('c').value_name("CGROUP_DIR"))
            .subcommand(
                Command::new("query").about("query list of BPF programs attached to cgroup dir"),
            )
            .subcommand(
                Command::new("detach")
                    .about("detach BPF program by id")
                    .arg(
                        Arg::new("id")
                            .value_name("PROG_ID")
                            .required(true)
                            .help("ID of BPF program returned by query command"),
                    ),
            )
            .subcommand(
                Command::new("attach")
                    .about("compile rules to BPF and attach to cgroup dir")
                    .arg(
                        Arg::new("input_file")
                            .value_name("INPUT_FILE")
                            .required(true)
                            .help("File contains Vec<LinuxDeviceCgroup> in json format"),
                    ),
            )
    }

    fn parse_cgroupv1_device_rules<P: AsRef<Path>>(path: P) -> Result<Vec<LinuxDeviceCgroup>> {
        let content = std::fs::read_to_string(path)?;
        let devices = serde_json::from_str(&content)?;
        Ok(devices)
    }

    pub fn run() -> Result<()> {
        let matches = cli().get_matches();
        let cgroup_dir = matches.get_one::<String>("cgroup_dir").unwrap();
        let cgroup_fd = nix::dir::Dir::open(
            cgroup_dir.as_str(),
            OFlag::O_RDONLY | OFlag::O_DIRECTORY,
            Mode::from_bits(0o600).unwrap(),
        )?;
        match matches.subcommand() {
            Some(("query", _)) => {
                let progs = bpf::prog::query(cgroup_fd.as_raw_fd())?;
                for prog in &progs {
                    println!("prog: id={}, fd={}", prog.id, prog.fd);
                }
            }
            Some(("detach", submatch)) => {
                let prog_id = submatch.get_one::<String>("id").unwrap().parse::<u32>()?;
                let progs = bpf::prog::query(cgroup_fd.as_raw_fd())?;
                let prog = progs.iter().find(|v| v.id == prog_id);
                if prog.is_none() {
                    bail!("can't get prog fd by prog id");
                }

                bpf::prog::detach2(prog.unwrap().fd, cgroup_fd.as_raw_fd())?;
                println!("detach ok");
            }
            Some(("attach", submatch)) => {
                let input_file = submatch.get_one::<String>("input_file").unwrap();
                let rules = parse_cgroupv1_device_rules(input_file)?;
                let mut emulator = emulator::Emulator::with_default_allow(false);
                emulator.add_rules(&rules);
                let prog = program::Program::from_rules(&emulator.rules, emulator.default_allow)?;
                let prog_fd = bpf::prog::load(LICENSE, prog.bytecodes())?;
                bpf::prog::attach(prog_fd, cgroup_fd.as_raw_fd())?;
                println!("attach ok");
            }

            _ => unreachable!(),
        };
        Ok(())
    }
}

#[cfg(not(feature = "cgroupsv2_devices"))]
mod bpf {
    use anyhow::{Result, bail};

    pub fn run() -> Result<()> {
        if !cfg!(feature = "cgroupsv2_devices") {
            bail!("cgroupsv2_devices feature is not enabled");
        }

        unreachable!()
    }
}

fn main() -> Result<()> {
    env_logger::init();
    bpf::run()?;

    Ok(())
}

use std::path::PathBuf;
use std::process::{Command, Stdio};

use anyhow::Result;
use libcgroups::common::{CgroupConfig, CgroupManager, ControllerOpt, create_cgroup_manager};
use nix::unistd::Pid;
use oci_spec::runtime::{
    LinuxBlockIoBuilder, LinuxMemoryBuilder, LinuxResourcesBuilder, LinuxThrottleDeviceBuilder,
};
fn main() -> Result<()> {
    let cfg = CgroupConfig {
        cgroup_path: PathBuf::from("system.slice:youki:test"),
        systemd_cgroup: true,
        container_name: "test".to_owned(),
    };
    let manager = create_cgroup_manager(cfg)?;
    let mem_limit = 256 * 1024 * 1024;
    // Throttle rate in bytes per second (Bps) for the block IO device
    const THROTTLE_RATE_BPS: u64 = 1000;
    let rate: u64 = THROTTLE_RATE_BPS;
    let memory_resource = LinuxMemoryBuilder::default().limit(mem_limit).build()?;
    let device = LinuxThrottleDeviceBuilder::default()
        .major(259)
        .minor(0)
        .rate(rate)
        .build()?;
    let blkio = LinuxBlockIoBuilder::default()
        .throttle_read_bps_device(vec![device])
        .build()?;
    let resources = LinuxResourcesBuilder::default()
        .memory(memory_resource)
        .block_io(blkio)
        .build()?;
    let opts = ControllerOpt {
        resources: &resources,
        disable_oom_killer: false,
        oom_score_adj: None,
        freezer_state: None,
    };

    let pid = Pid::from_raw(std::process::id() as i32);
    manager.add_task(pid)?;
    manager.apply(&opts)?;

    println!("Cgroup created and properties applied.");
    println!("Launching interactive shell... (type exit to continue)");
    // use 'dd if=/dev/zero of=/tmp/test.bin bs=1M count=1024 oflag=direct' to test the read write speed
    // or check using 'systemctl --show youki-test.scope'
    Command::new("sh")
        .stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .spawn()
        .expect("Failed to spawn shell")
        .wait()
        .expect("Shell process failed");

    println!("Shell exited. Removing cgroup...");

    manager.remove()?;
    Ok(())
}

